user_message:
Compare the typed predicate candidates against the existing registry.
Candidate predicates:
[
  {
    "name": "PLANS_VERIFICATION_STEP",
    "definition": "The reasoning explicitly states a future targeted check or test intended to establish whether a required behavior, state, or integration works, rather than only stating an implementation or cleanup action.",
    "parameters": [
      {
        "name": "reasoning",
        "type": "reasoning",
        "description": "The agent text expressing the planned verification step."
      }
    ],
    "assertion_conditions": [
      "The reasoning identifies at least one future verification action or test.",
      "It states what the check should establish or what result is sought.",
      "The check is framed as confirmatory of behavior or state, not merely as a change to be made."
    ],
    "exclusion_conditions": [
      "The reasoning only reports a completed test or its result.",
      "The reasoning only announces an implementation, configuration, cleanup, or safeguard action without a verification purpose."
    ]
  },
  {
    "name": "IMPLEMENTS_CONFIGURATION_AS_SPECIFIED",
    "definition": "The action applies a configuration or configuration-like file whose specified settings correspond to an intended operational setup stated in the reasoning; the observation records that the change was successfully written or applied.",
    "parameters": [
      {
        "name": "configuration_action",
        "type": "action",
        "description": "The action writing or applying the configuration."
      },
      {
        "name": "intent_reasoning",
        "type": "reasoning",
        "description": "The reasoning specifying the intended configuration settings or behavior."
      },
      {
        "name": "application_observation",
        "type": "observation",
        "description": "The observation reporting whether the configuration was successfully written or applied."
      }
    ],
    "assertion_conditions": [
      "The reasoning specifies an intended setting, target, or configuration behavior.",
      "The action's content encodes those specified settings at a relevant path or scope.",
      "The observation reports successful creation or application of that configuration."
    ],
    "exclusion_conditions": [
      "The action does not implement the settings described in the reasoning.",
      "The observation reports failure or only an attempt.",
      "The reasoning only discusses a configuration without stating an intended change."
    ]
  },
  {
    "name": "PREFLIGHT_VALIDATES_CONFIGURATION",
    "definition": "Before activating or relying on a configuration, the action performs a validation check of syntax, linkage, or prerequisite consistency, and the observation confirms that the validation succeeded.",
    "parameters": [
      {
        "name": "validation_action",
        "type": "action",
        "description": "The action performing the configuration validation, possibly together with activation commands."
      },
      {
        "name": "validation_observation",
        "type": "observation",
        "description": "The observation reporting the validation result."
      }
    ],
    "assertion_conditions": [
      "The action includes a check whose purpose is to validate the configuration before activation.",
      "The observation reports a successful validation outcome, such as syntax OK or a correct link target.",
      "The validation is distinguishable from the activation or use action itself."
    ],
    "exclusion_conditions": [
      "The action directly activates the service without any validation step.",
      "The validation fails or its result is absent.",
      "The observation only shows that a process is running without validating configuration."
    ]
  },
  {
    "name": "VERIFIES_EXPECTED_BEHAVIOR",
    "definition": "A check action is performed to test a specific behavior or result that the reasoning has identified as expected, and the resulting observation reports a match to that expectation, confirming the behavior.",
    "parameters": [
      {
        "name": "expectation_reasoning",
        "type": "reasoning",
        "description": "The reasoning stating the expected behavior or result."
      },
      {
        "name": "check_action",
        "type": "action",
        "description": "The action directed at checking the expected behavior."
      },
      {
        "name": "result_observation",
        "type": "observation",
        "description": "The observation reporting the check result."
      }
    ],
    "assertion_conditions": [
      "The reasoning states the behavior or result that is expected to occur.",
      "The action is directed at observing that behavior or result.",
      "The observation reports content matching the expectation without contradiction."
    ],
    "exclusion_conditions": [
      "No expected behavior or result is identifiable in the reasoning.",
      "The action is unrelated or only incidental to the expectation.",
      "The observation contradicts the expectation or is ambiguous."
    ]
  },
  {
    "name": "TESTS_HYPOTHESIS_WITH_PROBE",
    "definition": "The reasoning identifies a specific uncertainty or hypothesis, a targeted action gathers evidence about it, and the resulting observation is interpretable as supporting or refuting that hypothesis.",
    "parameters": [
      {
        "name": "probe_action",
        "type": "action",
        "description": "The action performing the targeted investigation."
      },
      {
        "name": "hypothesis_reasoning",
        "type": "reasoning",
        "description": "The reasoning identifying the uncertainty or hypothesis being tested."
      },
      {
        "name": "probe_observation",
        "type": "observation",
        "description": "The observation reporting evidence relevant to the hypothesis."
      }
    ],
    "assertion_conditions": [
      "The reasoning states a specific hypothesis or unresolved question.",
      "The probe action is designed to obtain evidence relevant to it.",
      "The observation contains evidence that addresses the hypothesis."
    ],
    "exclusion_conditions": [
      "The reasoning contains no identifiable hypothesis or uncertainty.",
      "The action is not directed at the hypothesis.",
      "The observation does not address the hypothesis."
    ]
  },
  {
    "name": "DIAGNOSES_FAILURE_CAUSE",
    "definition": "The reasoning explains an observed failure, error, or unexpected result by identifying a specific causal mechanism or condition responsible for it.",
    "parameters": [
      {
        "name": "diagnostic_reasoning",
        "type": "reasoning",
        "description": "The reasoning identifying and explaining the cause of the failure."
      },
      {
        "name": "failure_observation",
        "type": "observation",
        "description": "The observation reporting the failure or unexpected result."
      }
    ],
    "assertion_conditions": [
      "The observation reports an error, failure, or unexpected absence of a result.",
      "The reasoning identifies a specific cause or condition and connects it to the failure.",
      "The diagnosis is more than a restatement of the error text."
    ],
    "exclusion_conditions": [
      "The reasoning merely repeats the failure without explaining its cause.",
      "The reasoning speculates without an identifiable link to the observation.",
      "The observation does not report a failure or unexpected result."
    ]
  },
  {
    "name": "CLASSIFIES_FAILURE_AS_TEST_ARTIFACT",
    "definition": "The reasoning determines that an observed failure arises from the agent's own test setup, execution context, or tooling rather than from a defect in the target system.",
    "parameters": [
      {
        "name": "assessment_reasoning",
        "type": "reasoning",
        "description": "The reasoning classifying the failure as an artifact of testing or environment."
      },
      {
        "name": "failure_observation",
        "type": "observation",
        "description": "The observation reporting the failure or anomalous result."
      }
    ],
    "assertion_conditions": [
      "The observation reports a failure, error, or anomalous result.",
      "The reasoning attributes that result to the agent's test setup, execution context, or tooling.",
      "The reasoning distinguishes this artifact from a genuine target-system problem."
    ],
    "exclusion_conditions": [
      "The reasoning treats the failure as a genuine defect of the target system.",
      "The reasoning only restates the failure or diagnoses a cause without classifying it as test-induced.",
      "The observation is not a failure."
    ]
  },
  {
    "name": "SUCCESSFUL_CORRECTIVE_RETRY",
    "definition": "After an observed failure is diagnosed, a retry action changes the failed operation in a way that addresses the diagnosed cause, and a subsequent observation shows that the retry succeeded or that the failure no longer occurs.",
    "parameters": [
      {
        "name": "failure_observation",
        "type": "observation",
        "description": "The observation reporting the initial failed or blocked operation."
      },
      {
        "name": "diagnosis_reasoning",
        "type": "reasoning",
        "description": "The reasoning identifying the cause of the failure and motivating the correction."
      },
      {
        "name": "retry_action",
        "type": "action",
        "description": "The revised action attempting the operation with a corrective change."
      },
      {
        "name": "retry_observation",
        "type": "observation",
        "description": "The observation reporting the result of the retry."
      }
    ],
    "assertion_conditions": [
      "The failure observation reports the initial failed or blocked operation.",
      "The diagnosis reasoning identifies a specific cause of that failure.",
      "The retry action differs from the failed action in a manner targeting the diagnosed cause.",
      "The retry observation reports success or absence of the prior failure."
    ],
    "exclusion_conditions": [
      "The retry repeats the original action without addressing the diagnosis.",
      "The failure cause is not diagnosed.",
      "The retry observation still shows the same failure or is unavailable."
    ]
  },
  {
    "name": "CONCLUDES_REQUIRED_CONDITION_SATISFIED",
    "definition": "The reasoning explicitly concludes that a required condition or goal-relevant state has been achieved, based on observed evidence or completed checks.",
    "parameters": [
      {
        "name": "conclusion_reasoning",
        "type": "reasoning",
        "description": "The reasoning asserting that the required condition or state is satisfied."
      }
    ],
    "assertion_conditions": [
      "The reasoning asserts that a specified required condition or goal state is satisfied.",
      "The assertion is presented as a conclusion about achieved state, not merely a future intention."
    ],
    "exclusion_conditions": [
      "The reasoning only plans or requests a future check or change.",
      "The reasoning only reports raw observations without stating that a required condition is satisfied."
    ]
  },
  {
    "name": "PLANS_CLEANUP_OR_RESTORATION",
    "definition": "The reasoning explicitly intends to remove artifacts produced during testing or to restore a system, repository, or data store to a clean initial state.",
    "parameters": [
      {
        "name": "cleanup_reasoning",
        "type": "reasoning",
        "description": "The reasoning expressing the cleanup or restoration intention."
      }
    ],
    "assertion_conditions": [
      "The reasoning identifies artifacts to remove, changes to revert, or an initial state to restore.",
      "It frames these as future cleanup or restoration actions."
    ],
    "exclusion_conditions": [
      "The reasoning only performs an implementation, configuration, or verification step.",
      "No cleanup or restoration intent is present."
    ]
  },
  {
    "name": "IMPLEMENTS_PREVENTIVE_SAFEGUARD",
    "definition": "The reasoning anticipates a plausible future failure or degraded condition, and the action creates or configures a mechanism intended to prevent that condition or automatically recover from it.",
    "parameters": [
      {
        "name": "safeguard_action",
        "type": "action",
        "description": "The action implementing the preventive or recovery mechanism."
      },
      {
        "name": "risk_reasoning",
        "type": "reasoning",
        "description": "The reasoning identifying the future failure or persistence risk."
      }
    ],
    "assertion_conditions": [
      "The reasoning identifies a plausible future failure or persistence risk.",
      "The action implements an idempotent or automatic safeguard or fallback addressing that risk.",
      "The safeguard is not merely a direct fix for a currently observed failure."
    ],
    "exclusion_conditions": [
      "The action only repairs a present failure without addressing future risk.",
      "No future failure or persistence risk is identified.",
      "The action does not implement a preventive or recovery mechanism."
    ]
  },
  {
    "name": "GROUNDS_CONCLUSION_IN_OBSERVATION",
    "definition": "The reasoning draws a conclusion or assessment using identifiable information from the observation as supporting evidence.",
    "parameters": [
      {
        "name": "conclusion_reasoning",
        "type": "reasoning",
        "description": "The reasoning expressing the evidence-based conclusion or assessment."
      },
      {
        "name": "evidence_observation",
        "type": "observation",
        "description": "The observation supplying evidence for that conclusion."
      }
    ],
    "assertion_conditions": [
      "The reasoning states a conclusion, assessment, or interpretation supported by content in the observation.",
      "The observation contains identifiable information that evidentially supports that conclusion."
    ],
    "exclusion_conditions": [
      "The reasoning merely repeats the observation without drawing a conclusion.",
      "The observation is unrelated to the conclusion or provides no identifiable support."
    ]
  }
]

Existing registry:
[
  {
    "name": "IS_PLAN",
    "definition": "The reasoning explicitly expresses at least one intended future action or sequence of actions to be taken in service of the task.",
    "parameters": [
      {
        "name": "reasoning",
        "type": "reasoning",
        "description": "The agent text expressing an intended future action or plan."
      }
    ],
    "assertion_conditions": [
      "The reasoning explicitly identifies at least one operation or sequence of operations that the agent intends to perform later.",
      "The intended action is presented as something to be done, not merely as a completed observation or factual statement."
    ],
    "exclusion_conditions": [
      "The reasoning only reports actions that have already been completed.",
      "The reasoning states a fact or diagnosis without expressing any intended future action."
    ]
  },
  {
    "name": "ACTION_IMPLEMENTS_PLANNED_STEP",
    "definition": "A recorded action carries out an operation that a reasoning node explicitly proposed as a future step, with matching task purpose rather than merely topical or temporal adjacency.",
    "parameters": [
      {
        "name": "action",
        "type": "action",
        "description": "The recorded tool invocation that performs the step."
      },
      {
        "name": "plan_reasoning",
        "type": "reasoning",
        "description": "The reasoning node that proposes the future operation."
      }
    ],
    "assertion_conditions": [
      "The plan_reasoning expresses an intended future operation or set of operations.",
      "The action performs an operation consistent with the purpose and target of the proposed step."
    ],
    "exclusion_conditions": [
      "The reasoning only describes past or completed actions.",
      "The action is unrelated to the proposed step or serves a different purpose.",
      "The connection is based only on temporal adjacency without matching intent."
    ]
  },
  {
    "name": "DIAGNOSES_OBSERVED_ARTIFACT_DEFECT",
    "definition": "The reasoning interprets content of an artifact exposed in an observation and identifies a specific missing, incomplete, or erroneous element that must be repaired.",
    "parameters": [
      {
        "name": "diagnosis_reasoning",
        "type": "reasoning",
        "description": "The reasoning that identifies the artifact defect or incompleteness."
