      {
        "name": "artifact_observation",
        "type": "observation",
        "description": "The observation exposing the artifact content being diagnosed."
      }
    ],
    "assertion_conditions": [
      "The observation exposes identifiable content of an artifact.",
      "The reasoning identifies a specific defect, gap, or incomplete element in that artifact relative to the intended requirement."
    ],
    "exclusion_conditions": [
      "The reasoning merely repeats or paraphrases the artifact content without identifying a defect.",
      "No specific missing, incomplete, or erroneous element is identified.",
      "The observation does not expose artifact content relevant to the diagnosis."
    ]
  },
  {
    "name": "PROPOSES_ARTIFACT_REPAIR",
    "definition": "The reasoning specifies a concrete correction or completion for an observed artifact defect, including replacement content or steps intended to make the artifact satisfy the requirement.",
    "parameters": [
      {
        "name": "repair_reasoning",
        "type": "reasoning",
        "description": "The reasoning containing the proposed repair or completion."
      }
    ],
    "assertion_conditions": [
      "The reasoning identifies at least one concrete change, replacement, or added step intended to repair or complete an artifact.",
      "The proposed repair is tied to an identified defect or requirement rather than being a generic intention to fix something."
    ],
    "exclusion_conditions": [
      "The reasoning only identifies a defect without proposing how to repair it.",
      "The reasoning expresses only a generic intention to fix or improve without concrete content or steps."
    ]
